import Link from "next/link";import {updateVendor} from "../../../_actions/commercial";import {createClient} from "@/lib/supabase/server";export const dynamic="force-dynamic";export default async function Page({params,searchParams}:{params:Promise<{id:string}>;searchParams:Promise<{error?:string}>}){const {id}=await params,q=await searchParams,s=await createClient();if(!s)return null;const [rr,vr,cr]=await Promise.all([s.from("vendors").select("*").eq("id",id).maybeSingle(),s.from("vendors").select("id,vendor_name").neq("id",id).eq("is_active",true),s.from("currencies").select("id,code").eq("is_active",true)]);const x=rr.data;if(!x)return <div>Vendor not found.</div>;return <div className="mx-auto max-w-5xl"><div className="flex justify-between"><h1 className="text-3xl font-bold">Edit Vendor</h1><Link href="/vendors" className="font-bold text-blue-700">Back</Link></div>{q.error?<div className="mt-5 rounded-xl border border-red-200 bg-red-50 p-4 text-red-700">{q.error}</div>:null}<form action={updateVendor} className="mccs-card mt-7 rounded-2xl p-6"><input type="hidden" name="vendor_id" value={id}/><div className="grid gap-5 md:grid-cols-2"><F l="Vendor Name *"><input name="vendor_name" defaultValue={x.vendor_name||""} required className="input"/></F><F l="Vendor Code"><input name="vendor_code" defaultValue={x.vendor_code||""} className="input"/></F><F l="Legal Name"><input name="legal_name" defaultValue={x.legal_name||""} className="input"/></F><F l="Relationship"><select name="relationship_type" defaultValue={x.relationship_type||"direct_contractor"} className="input"><option value="direct_contractor">Direct Contractor</option><option value="subcontractor">Subcontractor</option><option value="supplier">Supplier</option><option value="consultant">Consultant</option></select></F><F l="Parent Vendor"><select name="parent_vendor_id" defaultValue={x.parent_vendor_id||""} className="input"><option value="">None</option>{(vr.data??[]).map((v:any)=><option key={v.id} value={v.id}>{v.vendor_name}</option>)}</select></F><F l="Default Currency"><select name="default_currency_id" defaultValue={x.default_currency_id||""} className="input"><option value="">None</option>{(cr.data??[]).map((v:any)=><option key={v.id} value={v.id}>{v.code}</option>)}</select></F><F l="Country"><input name="country" defaultValue={x.country||""} className="input"/></F><F l="Contact Person"><input name="contact_person" defaultValue={x.contact_person||""} className="input"/></F><F l="Email"><input name="email" defaultValue={x.email||""} className="input"/></F><F l="Phone"><input name="phone" defaultValue={x.phone||""} className="input"/></F><F l="Tax Number"><input name="tax_number" defaultValue={x.tax_number||""} className="input"/></F><F l="Address"><input name="address" defaultValue={x.address||""} className="input"/></F></div><label className="mt-5 flex items-center gap-3"><input type="checkbox" name="is_active" defaultChecked={!!x.is_active}/> Active vendor</label><F l="Notes"><textarea name="notes" defaultValue={x.notes||""} rows={3} className="input mt-5"/></F><div className="mt-7 flex justify-end"><button className="rounded-xl bg-[#07111f] px-5 py-3 text-sm font-bold text-white dark:bg-blue-600">Save Vendor</button></div></form></div>}
function F({l,children}:{l:string;children:React.ReactNode}){return <label><span className="mb-2 block text-sm font-bold text-slate-700 dark:text-slate-200">{l}</span>{children}</label>}